import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import { basename, dirname, join, resolve } from 'node:path';

export const READING = 'reading';
export const FINISHED = 'finished';

const TITLE_MAX = 200;
const AUTHOR_MAX = 200;
const NOTES_MAX = 5000;

export class ValidationError extends Error {
  constructor(errors) {
    super(errors.join(' '));
    this.name = 'ValidationError';
    this.errors = errors;
  }
}

export function resolveBooksFile(filePath = process.env.BOOKS_FILE) {
  return resolve(filePath || join(process.cwd(), 'data', 'books.json'));
}

function createLock() {
  let tail = Promise.resolve();
  return function run(fn) {
    const result = tail.then(fn, fn);
    tail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  };
}

function textField(value, label, { required, max }) {
  if (value == null) value = '';
  if (typeof value !== 'string') {
    return { cleaned: '', errors: [`${label} must be text.`] };
  }
  const cleaned = value.replace(/\r\n/g, '\n').trim();
  const errors = [];
  if (required && cleaned.length === 0) errors.push(`${label} is required.`);
  if (cleaned.length > max) errors.push(`${label} must be ${max} characters or fewer.`);
  return { cleaned, errors };
}

function newId(books) {
  const used = new Set(books.map((book) => book && book.id));
  for (let attempt = 0; attempt < 5; attempt += 1) {
    const id = randomBytes(6).toString('base64url');
    if (!used.has(id)) return id;
  }
  return randomBytes(9).toString('base64url');
}

export function createStore(filePath = resolveBooksFile()) {
  const run = createLock();

  async function read() {
    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (err) {
      if (err && err.code === 'ENOENT') return [];
      throw err;
    }
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch {
      const error = new Error(`Books file is not valid JSON: ${filePath}`);
      error.code = 'BOOKS_CORRUPT';
      throw error;
    }
    if (!Array.isArray(parsed)) {
      const error = new Error(`Books file must contain a JSON array: ${filePath}`);
      error.code = 'BOOKS_CORRUPT';
      throw error;
    }
    return parsed;
  }

  async function write(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = join(
      dirname(filePath),
      `.${basename(filePath)}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`,
    );
    try {
      await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
      await rename(tmp, filePath);
    } catch (err) {
      await rm(tmp, { force: true });
      throw err;
    }
  }

  return {
    filePath,
    list() {
      return run(read);
    },
    get(id) {
      return run(async () => {
        const books = await read();
        return books.find((book) => book && book.id === id) ?? null;
      });
    },
    add(input) {
      return run(async () => {
        const title = textField(input?.title, 'Title', { required: true, max: TITLE_MAX });
        const author = textField(input?.author, 'Author', { required: true, max: AUTHOR_MAX });
        const notes = textField(input?.notes, 'Notes', { required: false, max: NOTES_MAX });
        const errors = [...title.errors, ...author.errors, ...notes.errors];
        if (errors.length > 0) throw new ValidationError(errors);

        const books = await read();
        const book = {
          id: newId(books),
          title: title.cleaned,
          author: author.cleaned,
          notes: notes.cleaned,
          status: READING,
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await write(books);
        return book;
      });
    },
    finish(id) {
      return run(async () => {
        const books = await read();
        const book = books.find((item) => item && item.id === id);
        if (!book) return null;
        if (book.status !== FINISHED) {
          book.status = FINISHED;
          book.finishedAt = new Date().toISOString();
          await write(books);
        }
        return book;
      });
    },
    updateNotes(id, notesInput) {
      return run(async () => {
        const books = await read();
        const book = books.find((item) => item && item.id === id);
        if (!book) return null;
        const notes = textField(notesInput, 'Notes', { required: false, max: NOTES_MAX });
        if (notes.errors.length > 0) throw new ValidationError(notes.errors);
        book.notes = notes.cleaned;
        await write(books);
        return book;
      });
    },
  };
}

