import { relative, isAbsolute } from 'node:path';
import { FINISHED } from './store.js';

const dateFormat = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'UTC',
});

export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function bookPath(id) {
  return `/books/${encodeURIComponent(id)}`;
}

function displayBooksPath(filePath) {
  const rel = relative(process.cwd(), filePath);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return filePath;
  return rel;
}

function formatDate(iso) {
  if (!iso) return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return dateFormat.format(date);
}

function href(id, suffix = '') {
  return escapeHtml(`${bookPath(id)}${suffix}`);
}

function errorsBlock(errors) {
  if (!errors || errors.length === 0) return '';
  const items = errors.map((error) => `<p>${escapeHtml(error)}</p>`).join('');
  return `<div class="errors" role="alert">${items}</div>`;
}

function footer(dataFile) {
  const where = dataFile
    ? `Saved in <code>${escapeHtml(displayBooksPath(dataFile))}</code>. No account.`
    : 'Saved on this computer. No account.';
  return `<footer><p>${where}</p></footer>`;
}

function header({ home }) {
  const brand = home
    ? '<h1><a href="/">Books</a></h1>'
    : '<p class="brand"><a href="/">Books</a></p>';
  const action = home
    ? '<a class="add" href="/books/new">Add a book</a>'
    : '<nav><a class="quiet" href="/">All books</a><a class="add" href="/books/new">Add a book</a></nav>';
  return `<header>${brand}${action}</header>`;
}

function layout({ title, description, body, canonical, home = false, dataFile }) {
  const safeTitle = escapeHtml(title);
  const safeDescription = escapeHtml(description || 'Books you are reading and books you have finished.');
  const canonicalTag = canonical
    ? `<link rel="canonical" href="${escapeHtml(canonical)}">`
    : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="${safeDescription}">
  <meta name="robots" content="noindex">
  <meta name="theme-color" content="#f4efe6">
  <meta property="og:title" content="${safeTitle}">
  <meta property="og:description" content="${safeDescription}">
  <meta property="og:type" content="article">
  ${canonical ? `<meta property="og:url" content="${escapeHtml(canonical)}">` : ''}
  ${canonicalTag}
  <title>${safeTitle}</title>
  <style>
    :root {
      color-scheme: light;
      --paper: #f4efe6;
      --card: #fffdf8;
      --ink: #1f1a17;
      --muted: #5e574f;
      --line: #e3d9cb;
      --accent: #7c3a2d;
      --accent-ink: #fffaf6;
      --finished: #3d5a45;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      background: var(--paper);
      color: var(--ink);
      font: 18px/1.5 "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
      border-top: 6px solid var(--accent);
    }
    .wrap {
      width: min(40rem, calc(100% - 2rem));
      margin: 0 auto;
      padding: 2.25rem 0 4rem;
    }
    a { color: var(--accent); }
    header {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 0.75rem 1rem;
      margin-bottom: 2rem;
      padding-bottom: 0.85rem;
      border-bottom: 1px solid var(--line);
    }
    header h1, .brand { margin: 0; font-size: 1.35rem; letter-spacing: 0.03em; }
    header h1 a, .brand a { color: inherit; text-decoration: none; }
    nav { display: flex; align-items: center; gap: 0.9rem; }
    a.quiet {
      font: 0.85rem/1 system-ui, sans-serif;
      color: var(--muted);
      text-decoration: none;
    }
    a.quiet:hover { color: var(--ink); }
    a.add, button {
      font: 600 0.82rem/1 system-ui, sans-serif;
      border-radius: 999px;
      padding: 0.5rem 0.85rem;
      text-decoration: none;
      display: inline-block;
    }
    a.add, button.primary {
      background: var(--accent);
      color: var(--accent-ink);
      border: 1px solid var(--accent);
    }
    button {
      background: transparent;
      color: var(--accent);
      border: 1px solid var(--accent);
      cursor: pointer;
    }
    a.add:hover, button.primary:hover { background: #642e24; border-color: #642e24; }
    button:hover { background: var(--accent); color: var(--accent-ink); }
    h1, h2, h3 { font-weight: 500; letter-spacing: -0.02em; }
    .section-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 1rem;
      margin: 0 0 0.35rem;
    }
    .section-head h2, .kicker {
      margin: 0;
      font-family: system-ui, sans-serif;
      font-size: 0.75rem;
      font-weight: 650;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--muted);
    }
    .count {
      font: 0.8rem/1 system-ui, sans-serif;
      color: var(--muted);
    }
    section + section { margin-top: 2.4rem; }
    .book-list {
      list-style: none;
      margin: 0;
      padding: 0;
      border-bottom: 1px solid var(--line);
    }
    .book {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 0.75rem 1rem;
      padding: 0.95rem 0;
      border-top: 1px solid var(--line);
    }
    .book-link { color: inherit; text-decoration: none; }
    .book-link h3 { margin: 0; font-size: 1.28rem; overflow-wrap: anywhere; }
    .book-link:hover h3, .book-link:focus-visible h3 { text-decoration: underline; }
    .author, .byline { color: var(--muted); }
    .author {
      margin: 0.15rem 0 0;
      font: 0.92rem/1.35 system-ui, sans-serif;
    }
    .empty { margin: 0.4rem 0 0; color: var(--muted); font-style: italic; }
    .book-title {
      margin: 0.35rem 0 0;
      font-size: 2.05rem;
      line-height: 1.15;
      overflow-wrap: anywhere;
    }
    .byline { margin: 0.45rem 0 0; font-size: 1.15rem; }
    .status { margin: 0; }
    .status-reading { color: var(--accent); }
    .status-finished { color: var(--finished); }
    .notes {
      white-space: pre-wrap;
      overflow-wrap: anywhere;
      margin: 0.8rem 0 0;
    }
    .panel {
      margin-top: 2rem;
      padding-top: 1.2rem;
      border-top: 1px solid var(--line);
    }
    .panel h2 { margin-bottom: 0.75rem; }
    .share-link { overflow-wrap: anywhere; }
    label {
      display: block;
      margin: 0 0 1rem;
      font: 0.82rem/1.3 system-ui, sans-serif;
    }
    input, textarea {
      display: block;
      width: 100%;
      margin-top: 0.35rem;
      padding: 0.6rem 0.7rem;
      border: 1px solid #d9cdb8;
      border-radius: 0.35rem;
      background: var(--card);
      color: var(--ink);
      font: 1.05rem/1.4 "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
    }
    textarea { min-height: 8rem; resize: vertical; }
    input[readonly] { color: var(--muted); }
    .errors {
      margin: 0 0 1.2rem;
      padding: 0.7rem 0.85rem;
      background: #f6e4de;
      color: #6a2d24;
      font: 0.9rem/1.4 system-ui, sans-serif;
    }
    .errors p { margin: 0.15rem 0; }
    footer {
      margin-top: 3rem;
      color: var(--muted);
      font: 0.8rem/1.4 system-ui, sans-serif;
    }
    footer code { font-size: 0.92em; }
    .skip {
      position: absolute;
      left: -999px;
      top: 0;
    }
    .skip:focus {
      left: 1rem;
      top: 1rem;
      background: white;
      padding: 0.4rem 0.6rem;
      z-index: 1;
    }
    a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
    }
    form.inline { margin: 0; }
    @media (max-width: 480px) {
      body { font-size: 17px; }
      .wrap { width: min(40rem, calc(100% - 1.5rem)); }
      .book-title { font-size: 1.7rem; }
    }
  </style>
</head>
<body>
  <a class="skip" href="#content">Skip to content</a>
  <div class="wrap">
    ${header({ home })}
    <main id="content">
      ${body}
    </main>
    ${footer(dataFile)}
  </div>
</body>
</html>
`;
}

function bookList(books, { finish }) {
  if (books.length === 0) return '';
  const items = books
    .map((book) => {
      const finishForm = finish
        ? `<form class="inline" method="post" action="${href(book.id, '/finish')}">
            <input type="hidden" name="next" value="home">
            <button type="submit" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark as finished</button>
          </form>`
        : '';
      return `<li class="book">
        <a class="book-link" href="${href(book.id)}">
          <h3>${escapeHtml(book.title)}</h3>
          <p class="author">${escapeHtml(book.author || 'Unknown author')}</p>
        </a>
        ${finishForm}
      </li>`;
    })
    .join('');
  return `<ul class="book-list">${items}</ul>`;
}

function usable(books) {
  return (Array.isArray(books) ? books : []).filter(
    (book) => book && typeof book === 'object' && typeof book.id === 'string' && typeof book.title === 'string',
  );
}

export function renderHome(books, { dataFile } = {}) {
  const all = usable(books);
  const reading = all
    .filter((book) => book.status !== FINISHED)
    .sort((a, b) => String(b.addedAt || '').localeCompare(String(a.addedAt || '')));
  const finished = all
    .filter((book) => book.status === FINISHED)
    .sort((a, b) => String(b.finishedAt || '').localeCompare(String(a.finishedAt || '')));
  const readingList = reading.length
    ? bookList(reading, { finish: true })
    : '<p class="empty">No books in progress. <a href="/books/new">Add a book</a>.</p>';
  const finishedList = finished.length
    ? bookList(finished, { finish: false })
    : '<p class="empty">No finished books yet.</p>';
  return layout({
    title: 'Books',
    description: 'Books you are reading and books you have finished.',
    home: true,
    dataFile,
    body: `<section id="reading">
        <div class="section-head">
          <h2>Currently reading</h2>
          <span class="count">${reading.length}</span>
        </div>
        ${readingList}
      </section>
      <section id="finished">
        <div class="section-head">
          <h2>Finished</h2>
          <span class="count">${finished.length}</span>
        </div>
        ${finishedList}
      </section>`,
  });
}

export function renderAdd({ errors = [], values = {}, dataFile } = {}) {
  const title = values.title ?? '';
  const author = values.author ?? '';
  const notes = values.notes ?? '';
  const titleInvalid = errors.some((error) => error.startsWith('Title')) ? ' aria-invalid="true"' : '';
  const authorInvalid = errors.some((error) => error.startsWith('Author')) ? ' aria-invalid="true"' : '';
  const notesInvalid = errors.some((error) => error.startsWith('Notes')) ? ' aria-invalid="true"' : '';
  return layout({
    title: 'Add a book · Books',
    description: 'Add a book you are reading.',
    dataFile,
    body: `<h1>Add a book</h1>
      ${errorsBlock(errors)}
      <form method="post" action="/books" accept-charset="UTF-8" autocomplete="off">
        <label for="title">Title
          <input id="title" name="title" type="text" required maxlength="200" autofocus value="${escapeHtml(title)}"${titleInvalid}>
        </label>
        <label for="author">Author
          <input id="author" name="author" type="text" required maxlength="200" value="${escapeHtml(author)}"${authorInvalid}>
        </label>
        <label for="notes">Notes
          <textarea id="notes" name="notes" maxlength="5000"${notesInvalid}>${escapeHtml(notes)}</textarea>
        </label>
        <button class="primary" type="submit">Add book</button>
      </form>`,
  });
}

function excerpt(notes) {
  const flat = String(notes || '').replace(/\s+/g, ' ').trim();
  if (!flat) return '';
  return flat.length > 140 ? `${flat.slice(0, 137)}...` : flat;
}

export function renderBook(book, { shareUrl, errors = [], notesValue, dataFile } = {}) {
  const notes = notesValue !== undefined ? notesValue : book.notes || '';
  const finished = book.status === FINISHED;
  const finishedOn = finished ? formatDate(book.finishedAt) : '';
  const status = finished
    ? `Finished${finishedOn ? ` · ${finishedOn}` : ''}`
    : 'Currently reading';
  const statusClass = finished ? 'status-finished' : 'status-reading';
  const notesHtml = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="empty">No notes yet.</p>';
  const finishForm = finished
    ? ''
    : `<form method="post" action="${href(book.id, '/finish')}">
        <button type="submit">Mark as finished</button>
      </form>`;
  const description = [book.author, excerpt(book.notes)].filter(Boolean).join(' — ');
  return layout({
    title: `${book.title} · Books`,
    description: description || book.title,
    canonical: shareUrl,
    dataFile,
    body: `<article>
        <p class="kicker status ${statusClass}">${escapeHtml(status)}</p>
        <h1 class="book-title">${escapeHtml(book.title)}</h1>
        <p class="byline">${escapeHtml(book.author || 'Unknown author')}</p>
        <section>
          <h2 class="kicker">Notes</h2>
          ${notesHtml}
        </section>
      </article>
      <section class="panel">
        <h2 class="kicker">Share</h2>
        <p>Send this address to share just this book.</p>
        <p><a class="share-link" href="${escapeHtml(shareUrl || bookPath(book.id))}">${escapeHtml(shareUrl || bookPath(book.id))}</a></p>
      </section>
      <section class="panel">
        <h2 class="kicker">Update</h2>
        ${errorsBlock(errors)}
        <form method="post" action="${href(book.id, '/notes')}" accept-charset="UTF-8">
          <label for="notes">Notes
            <textarea id="notes" name="notes" maxlength="5000">${escapeHtml(notes)}</textarea>
          </label>
          <button class="primary" type="submit">Save notes</button>
        </form>
        ${finishForm}
      </section>`,
  });
}

export function renderNotFound(dataFile) {
  return layout({
    title: 'Book not found · Books',
