{"path":"/workspace/lib/pages.js","content":"import { relative, isAbsolute } from 'node:path';
import { FINISHED } from './store.js';

const dateFormat = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'UTC',
});

export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function bookPath(id) {
  return `/books/${encodeURIComponent(id)}`;
}

function displayBooksPath(filePath) {
  const rel = relative(process.cwd(), filePath);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return filePath;
  return rel;
}

function formatDate(iso) {
  if (!iso) return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return dateFormat.format(date);
}

function href(id, suffix = '') {
  return escapeHtml(`${bookPath(id)}${suffix}`);
}

function errorsBlock(errors) {
  if (!errors || errors.length === 0) return '';
  const items = errors.map((error) => `<p>${escapeHtml(error)}</p>`).join('');
  return `<div class="errors" role="alert">${items}</div>`;
}

function footer(dataFile) {
  const where = dataFile
    ? `Saved in <code>${escapeHtml(displayBooksPath(dataFile))}</code>. No account.`
    : 'Saved on this computer. No account.';
  return `<footer><p>${where}</p></footer>`;
}

function header({ home }) {
  const brand = home
    ? '<h1><a href="/">Books</a></h1>'
    : '<p class="brand"><a href="/">Books</a></p>';
  const action = home
    ? '<a class="add" href="/books/new">Add a book</a>'
    : '<nav><a class="quiet" href="/">All books</a><a class="add" href="/books/new">Add a book</a></nav>';
  return `<header>${brand}${action}</header>`;
}

function layout({ title, description, body, canonical, home = false, dataFile }) {
  const safeTitle = escapeHtml(title);
  const safeDescription = escapeHtml(description || 'Books you are reading and books you have finished.');
  const canonicalTag = canonical
    ? `<link rel="canonical" href="${escapeHtml(canonical)}">`
    : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="${safeDescription}">
  <meta name="robots" content="noindex">
  <meta name="theme-color" content="#f4efe6">
  <meta property="og:title" content="${safeTitle}">
  <meta property="og:description" content="${safeDescription}">
  <meta property="og:type" content="article">
  ${canonical ? `<meta property="og:url" content="${escapeHtml(canonical)}">` : ''}
  ${canonicalTag}
  <title>${safeTitle}</title>
  <style>
    :root {
      color-scheme: light;
      --paper: #f4efe6;
      --card: #fffdf8;
      --ink: #1f1a17;
      --muted: #5e574f;
      --line: #e3d9cb;
      --accent: #7c3a2d;
      --accent-ink: #fffaf6;
      --finished: #3d5a45;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      background: var(--paper);
      color: var(--ink);
      font: 18px/1.5 "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
      border-top: 6px solid var(--accent);
    }
    .wrap {
      width: min(40rem, calc(100% - 2rem));
      margin: 0 auto;
      padding: 2.25rem 0 4rem;
