      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 0.75rem 1rem;
      margin-bottom: 2rem;
      padding-bottom: 0.85rem;
      border-bottom: 1px solid var(--line);
    }
    header h1, .brand { margin: 0; font-size: 1.35rem; letter-spacing: 0.03em; }
    header h1 a, .brand a { color: inherit; text-decoration: none; }
    nav { display: flex; align-items: center; gap: 0.9rem; }
    a.quiet {
      font: 0.85rem/1 system-ui, sans-serif;
      color: var(--muted);
      text-decoration: none;
    }
    a.quiet:hover { color: var(--ink); }
    a.add, button {
      font: 600 0.82rem/1 system-ui, sans-serif;
      border-radius: 999px;
      padding: 0.5rem 0.85rem;
      text-decoration: none;
      display: inline-block;
    }
    a.add, button.primary {
      background: var(--accent);
      color: var(--accent-ink);
      border: 1px solid var(--accent);
    }
    button {
      background: transparent;
      color: var(--accent);
      border: 1px solid var(--accent);
      cursor: pointer;
    }
    a.add:hover, button.primary:hover { background: #642e24; border-color: #642e24; }
    button:hover { background: var(--accent); color: var(--accent-ink); }
    h1, h2, h3 { font-weight: 500; letter-spacing: -0.02em; }
