      background: var(--card);
      color: var(--ink);
      font: 1.05rem/1.4 "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
    }
    textarea { min-height: 8rem; resize: vertical; }
    input[readonly] { color: var(--muted); }
    .errors {
      margin: 0 0 1.2rem;
      padding: 0.7rem 0.85rem;
      background: #f6e4de;
      color: #6a2d24;
      font: 0.9rem/1.4 system-ui, sans-serif;
    }
    .errors p { margin: 0.15rem 0; }
    footer {
      margin-top: 3rem;
      color: var(--muted);
      font: 0.8rem/1.4 system-ui, sans-serif;
    }
    footer code { font-size: 0.92em; }
    .skip {
      position: absolute;
      left: -999px;
      top: 0;
    }
    .skip:focus {
      left: 1rem;
      top: 1rem;
      background: white;
      padding: 0.4rem 0.6rem;
      z-index: 1;
    }
    a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
    }
    form.inline { margin: 0; }
    @media (max-width: 480px) {
      body { font-size: 17px; }
      .wrap { width: min(40rem, calc(100% - 1.5rem)); }
      .book-title { font-size: 1.7rem; }
    }
  </style>
</head>
<body>
  <a class="skip" href="#content">Skip to content</a>
  <div class="wrap">
    ${header({ home })}
    <main id="content">
      ${body}
    </main>
    ${footer(dataFile)}
  </div>
</body>
</html>
`;
}

function bookList(books, { finish }) {
  if (books.length === 0) return '';
  const items = books
    .map((book) => {
      const finishForm = finish
        ? `<form class="inline" method="post" action="${href(book.id, '/finish')}">
            <input type="hidden" name="next" value="home">
            <button type="submit" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark as finished</button>
          </form>`
        : '';
      return `<li class="book">
        <a class="book-link" href="${href(book.id)}">
          <h3>${escapeHtml(book.title)}</h3>
          <p class="author">${escapeHtml(book.author || 'Unknown author')}</p>
        </a>
        ${finishForm}
      </li>`;
    })
    .join('');
  return `<ul class="book-list">${items}</ul>`;
}

function usable(books) {
  return (Array.isArray(books) ? books : []).filter(
    (book) => book && typeof book === 'object' && typeof book.id === 'string' && typeof book.title === 'string',
  );
}

export function renderHome(books, { dataFile } = {}) {
  const all = usable(books);
  const reading = all
    .filter((book) => book.status !== FINISHED)
    .sort((a, b) => String(b.addedAt || '').localeCompare(String(a.addedAt || '')));
  const finished = all
    .filter((book) => book.status === FINISHED)
    .sort((a, b) => String(b.finishedAt || '').localeCompare(String(a.finishedAt || '')));
  const readingList = reading.length
    ? bookList(reading, { finish: true })
    : '<p class="empty">No books in progress. <a href="/books/new">Add a book</a>.</p>';
  const finishedList = finished.length
    ? bookList(finished, { finish: false })
    : '<p class="empty">No finished books yet.</p>';
  return layout({
    title: 'Books',
    description: 'Books you are reading and books you have finished.',
    home: true,
    dataFile,
    body: `<section id="reading">
        <div class="section-head">
          <h2>Currently reading</h2>
          <span class="count">${reading.length}</span>
        </div>
        ${readingList}
      </section>
      <section id="finished">
        <div class="section-head">
          <h2>Finished</h2>
          <span class="count">${finished.length}</span>
        </div>
        ${finishedList}
      </section>`,
  });
}

export function renderAdd({ errors = [], values = {}, dataFile } = {}) {
  const title = values.title ?? '';
  const author = values.author ?? '';
  const notes = values.notes ?? '';
  const titleInvalid = errors.some((error) => error.startsWith('Title')) ? ' aria-invalid="true"' : '';
  const authorInvalid = errors.some((error) => error.startsWith('Author')) ? ' aria-invalid="true"' : '';
  const notesInvalid = errors.some((error) => error.startsWith('Notes')) ? ' aria-invalid="true"' : '';
  return layout({
    title: 'Add a book · Books',
    description: 'Add a book you are reading.',
    dataFile,
    body: `<h1>Add a book</h1>
      ${errorsBlock(errors)}
      <form method="post" action="/books" accept-charset="UTF-8" autocomplete="off">
        <label for="title">Title
          <input id="title" name="title" type="text" required maxlength="200" autofocus value="${escapeHtml(title)}"${titleInvalid}>
        </label>
        <label for="author">Author
          <input id="author" name="author" type="text" required maxlength="200" value="${escapeHtml(author)}"${authorInvalid}>
        </label>
        <label for="notes">Notes
          <textarea id="notes" name="notes" maxlength="5000"${notesInvalid}>${escapeHtml(notes)}</textarea>
        </label>
        <button class="primary" type="submit">Add book</button>
      </form>`,
  });
}

function excerpt(notes) {
  const flat = String(notes || '').replace(/\s+/g, ' ').trim();
  if (!flat) return '';
  return flat.length > 140 ? `${flat.slice(0, 137)}...` : flat;
}

export function renderBook(book, { shareUrl, errors = [], notesValue, dataFile } = {}) {
  const notes = notesValue !== undefined ? notesValue : book.notes || '';
  const finished = book.status === FINISHED;
  const finishedOn = finished ? formatDate(book.finishedAt) : '';
  const status = finished
    ? `Finished${finishedOn ? ` · ${finishedOn}` : ''}`
    : 'Currently reading';
  const statusClass = finished ? 'status-finished' : 'status-reading';
  const notesHtml = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="empty">No notes yet.</p>';
  const finishForm = finished
    ? ''
    : `<form method="post" action="${href(book.id, '/finish')}">
        <button type="submit">Mark as finished</button>
      </form>`;
  const description = [book.author, excerpt(book.notes)].filter(Boolean).join(' — ');
  return layout({
    title: `${book.title} · Books`,
    description: description || book.title,
    canonical: shareUrl,
    dataFile,
    body: `<article>
        <p class="kicker status ${statusClass}">${escapeHtml(status)}</p>
        <h1 class="book-title">${escapeHtml(book.title)}</h1>
        <p class="byline">${escapeHtml(book.author || 'Unknown author')}</p>
        <section>
          <h2 class="kicker">Notes</h2>
          ${notesHtml}
        </section>
      </article>
      <section class="panel">
        <h2 class="kicker">Share</h2>
        <p>Send this address to share just this book.</p>
        <p><a class="share-link" href="${escapeHtml(shareUrl || bookPath(book.id))}">${escapeHtml(shareUrl || bookPath(book.id))}</a></p>
      </section>
      <section class="panel">
        <h2 class="kicker">Update</h2>
        ${errorsBlock(errors)}
        <form method="post" action="${href(book.id, '/notes')}" accept-charset="UTF-8">
          <label for="notes">Notes
            <textarea id="notes" name="notes" maxlength="5000">${escapeHtml(notes)}</textarea>
          </label>
          <button class="primary" type="submit">Save notes</button>
        </form>
        ${finishForm}
      </section>`,
  });
}

export function renderNotFound(dataFile) {
  return layout({
    title: 'Book not found · Books',
    description: 'That link does not match a book on this shelf.',
    dataFile,
    body: `<h1>Book not found</h1>
      <p>That link does not match a book on this shelf.</p>`,
  });
}

export function renderMessage({ title, message, dataFile }) {
  return layout({
    title: `${title} · Books`,
    description: message,
    dataFile,
    body: `<h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p>`,
  });
}

export function renderError(dataFile) {
  return layout({
    title: 'Something went wrong · Books',
    description: 'The books file could not be read.',
    dataFile,
    body: `<h1>Something went wrong</h1>
      <p>The books file could not be read. Saved books were not changed.</p>`,
  });
}
