{"path":"/workspace/server.js","content":"import { createServer as createHttpServer } from 'node:http';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  renderAdd,
  renderBook,
  renderError,
  renderHome,
  renderMessage,
  renderNotFound,
  bookPath,
} from './lib/pages.js';
import { ValidationError, createStore, resolveBooksFile } from './lib/store.js';

const MAX_BODY = 64 * 1024;

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

function readPort(value) {
  if (value == null || value === '') return 3000;
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    console.error(`Invalid PORT: ${value}`);
    process.exit(1);
  }
  return port;
}

function origin(req) {
  const configured = process.env.BASE_URL;
  if (configured && /^https?:\/\/[A-Za-z0-9._:-]+$/.test(configured)) {
    return configured.replace(/\/$/, '');
  }
  const host = req.headers.host || 'localhost';
  if (!/^[A-Za-z0-9._:-]+$/.test(host)) return 'http://localhost';
  const forwarded = req.headers['x-forwarded-proto'];
  const proto = forwarded === 'https' ? 'https' : 'http';
  return `${proto}://${host}`;
}

function sendHtml(res, html, status = 200) {
  const body = Buffer.from(html, 'utf8');
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': body.length,
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    'Content-Security-Policy':
      "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
    'Referrer-Policy': 'same-origin',
  });
  res.end(body);
}

function redirect(res, req, path) {
  const location = `${origin(req)}${path}`;
  res.writeHead(303, {
    Location: location,
    'Cache-Control': 'no-store',
    'Content-Type': 'text/plain; charset=utf-8',
  });
  res.end(`See ${location}\n`);
}

function normalizePath(pathname) {
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

function matchBook(pathname) {
  const match = pathname.match(/^\/books\/([A-Za-z0-9_-]+)(?:\/(finish|notes))?$/);
  if (!match || match[1] === 'new') return null;
  return { id: match[1], action: match[2] || 'show' };
}

async function readForm(req) {
  const type = String(req.headers['content-type'] || '');
  if (!type.startsWith('application/x-www-form-urlencoded')) {
    throw new HttpError(415, 'Use the form on the page to save changes.');
  }
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) {
      req.destroy();
      throw new HttpError(413, 'That was too large to save.');
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

async function route(req, res, store) {
  const url = new URL(req.url || '/', 'http://127.0.0.1');
  const pathname = normalizePath(url.pathname);
  const method = req.method || 'GET';

  if (pathname === '/favicon.ico') {
    res.writeHead(204, { 'Cache-Control': 'no-store' });
    res.end();
    return;
  }

  if (method === 'GET' && pathname === '/') {
    sendHtml(res, renderHome(await store.list(), { dataFile: store.filePath }));
    return;
  }

  if (pathname === '/books' && method === 'GET') {
    redirect(res, req, '/');
    return;
  }

  if (pathname === '/books/new' && method === 'GET') {
    sendHtml(res, renderAdd({ errors: [], values: {}, dataFile: store.filePath }));
    return;
  }

  if (pathname === '/books' && method === 'POST') {
    const form = await readForm(req);
    const values = {
      title: form.get('title') ?? '',
      author: form.get('author') ?? '',
      notes: form.get('notes') ?? '',
    };
    try {
      const book = await store.add(values);
      redirect(res, req, bookPath(book.id));
    } catch (err) {
      if (!(err instanceof ValidationError)) throw err;
      sendHtml(res, renderAdd({ errors: err.errors, values, dataFile: store.filePath }), 400);
    }
    return;
  }

  const match = matchBook(pathname);
  if (!match) {
    sendHtml(res, renderNotFound(store.filePath), 404);
    return;
  }

  if (match.action === 'show' && method === 'GET') {
    const book = await store.get(match.id);
    if (!book) {
      sendHtml(res, renderNotFound(store.filePath), 404);
      return;
    }
    const shareUrl = `${origin(req)}${bookPath(book.id)}`;
    sendHtml(res, renderBook(book, { shareUrl, dataFile: store.filePath }));
    return;
  }

  if (match.action === 'finish' && method === 'POST') {
    const form = await readForm(req);
    const book = await store.finish(match.id);
    if (!book) {
      sendHtml(res, renderNotFound(store.filePath), 404);
      return;
    }
    redirect(res, req, form.get('next') === 'home' ? '/' : bookPath(book.id));
    return;
  }

  if (match.action === 'notes' && method === 'POST') {
    const form = await readForm(req);
    const notes = form.get('notes') ?? '';
    try {
      const book = await store.updateNotes(match.id, notes);
      if (!book) {
        sendHtml(res, renderNotFound(store.filePath), 404);
        return;
      }
      redirect(res, req, bookPath(book.id));
    } catch (err) {
      if (!(err instanceof ValidationError)) throw err;
      const book = await store.get(match.id);
      if (!book) {
        sendHtml(res, renderNotFound(store.filePath), 404);
        return;
      }
      sendHtml(
        res,
        renderBook(book, {
          shareUrl: `${origin(req)}${bookPath(book.id)}`,
          errors: err.errors,
          notesValue: notes,
          dataFile: store.filePath,
        }),
        400,
      );
    }
    return;
  }

  sendHtml(
    res,
    renderMessage({
      title: 'That action is not available',
      message: 'Use the buttons on the book page.',
      dataFile: store.filePath,
    }),
    405,
  );
}

export function createServer(options = {}) {
  const store = createStore(resolveBooksFile(options.booksFile));
  return createHttpServer((req, res) => {
    route(req, res, store).catch((err) => {
      if (res.headersSent) {
        res.end();
        return;
      }
      if (err instanceof HttpError) {
        sendHtml(res, renderMessage({ title: 'Try again', message: err.message, dataFile: store.filePath }), err.status);
        return;
      }
      console.error(err);
      sendHtml(res, renderError(store.filePath), 500);
    });
  });
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (isMain) {
  const port = readPort(process.env.PORT);
  const server = createServer();
  server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') console.error(`Port ${port} is already in use.`);
    else console.error(err.message);
    process.exit(1);
  });
  server.listen(port, '0.0.0.0', () => {
    const actual = server.address();
    const shown = actual && typeof actual === 'object' ? actual.port : port;
    console.log(`Books running at http://localhost:${shown}`);
    console.log(`Saving books to ${resolveBooksFile()}`);
  });
}
