import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createServer } from '../server.js';
import { createStore } from '../lib/store.js';

let dir;
let file;
let server;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
});

afterEach(async () => {
  if (server) {
    await new Promise((resolve) => server.close(resolve));
    server = undefined;
  }
  await rm(dir, { recursive: true, force: true });
});

async function start() {
  server = createServer({ booksFile: file });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('Expected a TCP port');
  return `http://127.0.0.1:${address.port}`;
}

function section(html, id) {
  const marker = `<section id="${id}">`;
  const start = html.indexOf(marker);
  expect(start).toBeGreaterThan(-1);
  const rest = html.slice(start);
  const end = rest.indexOf('</section>');
  expect(end).toBeGreaterThan(-1);
  return rest.slice(0, end);
}

async function postForm(base, path, fields) {
  return fetch(`${base}${path}`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

function bookIdFrom(location) {
  const url = new URL(location);
  const id = url.pathname.split('/').filter(Boolean)[1];
  expect(id).toBeTruthy();
  return id;
}

describe('store', () => {
  it('saves books to the JSON file and reads them back', async () => {
    const store = createStore(file);
    const book = await store.add({
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'The past does not stay put.',
    });
    const reloaded = createStore(file);
    const saved = await reloaded.get(book.id);
    expect(saved).toMatchObject({
      id: book.id,
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'The past does not stay put.',
      status: 'reading',
      finishedAt: null,
    });
    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toHaveLength(1);
  });

  it('marks a book finished without dropping notes', async () => {
    const store = createStore(file);
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Arrakis' });
    const finished = await store.finish(book.id);
    expect(finished.status).toBe('finished');
    expect(finished.notes).toBe('Arrakis');
    expect(finished.finishedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
    const again = await store.finish(book.id);
    expect(again.finishedAt).toBe(finished.finishedAt);
  });

  it('rejects an empty title and does not create the file', async () => {
    const store = createStore(file);
    await expect(store.add({ title: '   ', author: 'Someone', notes: '' })).rejects.toThrow(/Title is required/);
    await expect(readFile(file, 'utf8')).rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('does not overwrite a corrupt books file', async () => {
    await writeFile(file, '{', 'utf8');
    const store = createStore(file);
    await expect(store.add({ title: 'Dune', author: 'Frank Herbert', notes: '' })).rejects.toThrow(/not valid JSON/);
    expect(await readFile(file, 'utf8')).toBe('{');
  });
});

describe('pages', () => {
  it('shows currently reading and finished when opened', async () => {
    const base = await start();
    const res = await fetch(`${base}/`);
    expect(res.status).toBe(200);
    const body = await res.text();
    expect(section(body, 'reading')).toContain('Currently reading');
    expect(section(body, 'reading')).toContain('No books in progress.');
    expect(section(body, 'finished')).toContain('Finished');
    expect(section(body, 'finished')).toContain('No finished books yet.');
    expect(body).toContain('href="/books/new"');
    expect(body).toContain('No account');
  });

  it('adds a book from the form and opens it by link', async () => {
    const base = await start();
    const form = await fetch(`${base}/books/new`);
    expect(form.status).toBe(200);
    const formHtml = await form.text();
    expect(formHtml).toContain('name="title"');
    expect(formHtml).toContain('name="author"');
    expect(formHtml).toContain('name="notes"');

    const created = await postForm(base, '/books', {
      title: 'The Left Hand of Darkness',
      author: 'Ursula K. Le Guin',
      notes: 'Winter is a character.',
    });
    expect(created.status).toBe(303);
    const id = bookIdFrom(created.headers.get('location'));

    const page = await fetch(`${base}/books/${id}`);
    expect(page.status).toBe(200);
    const body = await page.text();
    expect(body).toContain('The Left Hand of Darkness');
    expect(body).toContain('Ursula K. Le Guin');
    expect(body).toContain('Winter is a character.');
    expect(body).toContain(`${base}/books/${id}`);

    const home = await fetch(`${base}/`);
    const homeHtml = await home.text();
    expect(section(homeHtml, 'reading')).toContain('The Left Hand of Darkness');
    expect(section(homeHtml, 'reading')).toContain(`href="/books/${id}"`);
    expect(section(homeHtml, 'finished')).not.toContain('The Left Hand of Darkness');
  });

  it('marks a book finished from the list and keeps it after restart', async () => {
    const base = await start();
    const first = await postForm(base, '/books', {
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'Dana',
    });
    const second = await postForm(base, '/books', {
      title: 'Parable of the Sower',
      author: 'Octavia E. Butler',
      notes: 'Earthseed',
    });
    const finishedId = bookIdFrom(first.headers.get('location'));
    const readingId = bookIdFrom(second.headers.get('location'));

    const marked = await postForm(base, `/books/${finishedId}/finish`, { next: 'home' });
    expect(marked.status).toBe(303);

    const home = await fetch(`${base}/`);
    const homeHtml = await home.text();
    expect(section(homeHtml, 'reading')).toContain('Parable of the Sower');
    expect(section(homeHtml, 'reading')).not.toContain('Kindred');
    expect(section(homeHtml, 'finished')).toContain('Kindred');
    expect(section(homeHtml, 'finished')).not.toContain('Mark as finished');

    await new Promise((resolve) => server.close(resolve));
    server = undefined;
    const restarted = await start();
    const page = await fetch(`${restarted}/books/${finishedId}`);
    expect(page.status).toBe(200);
    const body = await page.text();
    expect(body).toContain('Kindred');
    expect(body).toContain('Octavia E. Butler');
    expect(body).toContain('Dana');
    expect(body).toContain('Finished');
    expect(body).not.toContain('Mark as finished');
    const stillReading = await fetch(`${restarted}/books/${readingId}`);
    expect(stillReading.status).toBe(200);
  });

  it('escapes book text on the shared page', async () => {
    const base = await start();
    const created = await postForm(base, '/books', {
      title: '<script>alert("x")</script>',
      author: '"><img src=x onerror=alert(1)>',
      notes: '<b>bold</b>',
    });
    const id = bookIdFrom(created.headers.get('location'));
    const page = await fetch(`${base}/books/${id}`);
    const body = await page.text();
    expect(body).not.toContain('<script>alert');
    expect(body).not.toContain('<b>bold</b>');
    expect(body).toContain('&lt;script&gt;');
    expect(body).toContain('&lt;b&gt;bold&lt;/b&gt;');
    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved[0].title).toBe('<script>alert("x")</script>');
  });

  it('returns not found for an unknown book link', async () => {
    const base = await start();
    const res = await fetch(`${base}/books/missing`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain('Book not found');
  });

  it('keeps a rejected form from adding a book', async () => {
    const base = await start();
    const res = await postForm(base, '/books', { title: '', author: '', notes: 'hello' });
    expect(res.status).toBe(400);
    const body = await res.text();
    expect(body).toContain('Title is required.');
    expect(body).toContain('Author is required.');
    expect(body).toContain('hello');
    await expect(readFile(file, 'utf8')).rejects.toMatchObject({ code: 'ENOENT' });
  });
});

