    expect(body).toContain('Kindred');
    expect(body).toContain('Octavia E. Butler');
    expect(body).toContain('Dana');
    expect(body).toContain('Finished');
    expect(body).not.toContain('Mark as finished');
    const stillReading = await fetch(`${restarted}/books/${readingId}`);
    expect(stillReading.status).toBe(200);
  });

  it('escapes book text on the shared page', async () => {
    const base = await start();
    const created = await postForm(base, '/books', {
      title: '<script>alert("x")</script>',
      author: '"><img src=x onerror=alert(1)>',
      notes: '<b>bold</b>',
    });
    const id = bookIdFrom(created.headers.get('location'));
    const page = await fetch(`${base}/books/${id}`);
    const body = await page.text();
    expect(body).not.toContain('<script>alert');
    expect(body).not.toContain('<b>bold</b>');
    expect(body).toContain('&lt;script&gt;');
    expect(body).toContain('&lt;b&gt;bold&lt;/b&gt;');
    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved[0].title).toBe('<script>alert("x")</script>');
  });

  it('returns not found for an unknown book link', async () => {
    const base = await start();
    const res = await fetch(`${base}/books/missing`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain('Book not found');
  });

  it('keeps a rejected form from adding a book', async () => {
    const base = await start();
    const res = await postForm(base, '/books', { title: '', author: '', notes: 'hello' });
    expect(res.status).toBe(400);
    const body = await res.text();
    expect(body).toContain('Title is required.');
    expect(body).toContain('Author is required.');
    expect(body).toContain('hello');
    await expect(readFile(file, 'utf8')).rejects.toMatchObject({ code: 'ENOENT' });
  });
});
"}

