node --input-type=module -e "
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from './server.js';

const dir = await mkdtemp(join(tmpdir(), 'books-preview-'));
const file = join(dir, 'books.json');
const server = createServer({ booksFile: file });
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const port = server.address().port;
const base = 'http://127.0.0.1:' + port;

const home = await fetch(base + '/');
console.log('HOME', home.status);
const homeHtml = await home.text();
console.log(homeHtml.includes('Currently reading') && homeHtml.includes('Finished') ? 'home headings ok' : 'home headings missing');

const created = await fetch(base + '/books', {
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ title: 'Kindred', author: 'Octavia E. Butler', notes: 'First note' }),
  redirect: 'manual',
});
const loc = created.headers.get('location');
console.log('CREATE', created.status, loc);
const page = await fetch(loc);
const html = await page.text();
const id = new URL(loc).pathname.split('/').pop();
console.log('DETAIL', page.status, html.includes('Kindred'), html.includes('Octavia E. Butler'), html.includes('First note'), html.includes(loc));

const notes = await fetch(base + '/books/' + id + '/notes', {
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ notes: 'Updated note' }),
  redirect: 'manual',
});
console.log('NOTES', notes.status);
const updated = await (await fetch(loc)).text();
console.log('NOTES VISIBLE', updated.includes('Updated note'));

const finished = await fetch(base + '/books/' + id + '/finish', {
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ next: 'home' }),
  redirect: 'manual',
});
console.log('FINISH', finished.status, finished.headers.get('location'));
const after = await (await fetch(base + '/')).text();
const reading = after.split('<section id=\"finished\">')[0];
const done = after.split('<section id=\"finished\">')[1];
console.log('reading has kindred', reading.includes('Kindred'));
console.log('finished has kindred', done.includes('Kindred'));

await new Promise((resolve) => server.close(resolve));
await rm(dir, { recursive: true, force: true });
"

